import{_ as d,o as e,c as a,a0 as o}from"./chunks/framework.Cp0xpwNH.js";const p=JSON.parse('{"title":"Vocabulary Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"VOCABULARY_ROADMAP.md","filePath":"VOCABULARY_ROADMAP.md"}'),r={name:"VOCABULARY_ROADMAP.md"};function s(i,t,n,l,h,c){return e(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="vocabulary-roadmap" tabindex="-1">Vocabulary Roadmap <a class="header-anchor" href="#vocabulary-roadmap" aria-label="Permalink to &quot;Vocabulary Roadmap&quot;">​</a></h1><p>This document maps every vocabulary topic in the curriculum, tracking what words are taught, when, and how many.</p><p>This is the authoritative source for vocabulary progression.</p><p><strong>Status:</strong> To be completed in Phase 2</p><hr><h2 id="format" tabindex="-1">Format <a class="header-anchor" href="#format" aria-label="Permalink to &quot;Format&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| Topic | CEFR Level | Target Words | Lessons | Status | Notes |</span></span>
<span class="line"><span>|---|---|---|---|---|---|</span></span>
<span class="line"><span>| Greetings | A0 | 10 | A0-01 | Pending | Essential survival vocab |</span></span></code></pre></div><hr><h2 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h2><p><strong>Topic</strong> -- The semantic category (Family, Food, Work, etc.)</p><p><strong>CEFR Level</strong> -- What level this topic is primarily taught (A0, A1, A2, B1)</p><p><strong>Target Words</strong> -- How many words to teach in this topic at this level</p><p><strong>Lessons</strong> -- Which lessons introduce these words</p><p><strong>Status</strong> -- Complete / In Progress / Pending</p><p><strong>Notes</strong> -- Additional context</p><hr><h2 id="a0-vocabulary-topics" tabindex="-1">A0 Vocabulary Topics <a class="header-anchor" href="#a0-vocabulary-topics" aria-label="Permalink to &quot;A0 Vocabulary Topics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Level</th><th>Target</th><th>Lessons</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td>Phonetics</td><td>A0</td><td>25</td><td>A0-01</td><td>Complete</td><td>Alphabet, vowels, diphthongs, consonants, stress patterns</td></tr><tr><td>Greetings</td><td>A0</td><td>8</td><td>A0-01</td><td>Pending</td><td>Hello, goodbye, please, thank you</td></tr><tr><td>Family</td><td>A0</td><td>12</td><td>A0-02, A0-03</td><td>Pending</td><td>Parents, siblings, relatives</td></tr><tr><td>Home</td><td>A0</td><td>15</td><td>A0-03, A0-04</td><td>Pending</td><td>House, rooms, furniture</td></tr><tr><td>Colors</td><td>A0</td><td>10</td><td>A0-04</td><td>Pending</td><td>Basic colors</td></tr><tr><td>Numbers</td><td>A0</td><td>20</td><td>A0-05</td><td>Pending</td><td>0-100</td></tr><tr><td>Time</td><td>A0</td><td>12</td><td>A0-05, A0-06</td><td>Pending</td><td>Days, months, seasons</td></tr></tbody></table><hr><h2 id="a0-01-understanding-dutch-sounds-and-spelling" tabindex="-1">A0-01: Understanding Dutch Sounds and Spelling <a class="header-anchor" href="#a0-01-understanding-dutch-sounds-and-spelling" aria-label="Permalink to &quot;A0-01: Understanding Dutch Sounds and Spelling&quot;">​</a></h2><p><strong>CEFR Level:</strong> A0<br><strong>Competency:</strong> Understanding Dutch Sounds and Spelling<br><strong>Lesson ID:</strong> A0-01<br><strong>Topics:</strong> Alphabet letters, Short vowels, Long vowels, Diphthongs, Consonants, Stress patterns<br><strong>Total Words:</strong> 25<br><strong>Status:</strong> Complete ✅</p><p>This lesson focuses on <strong>phonetic teaching examples</strong> rather than everyday vocabulary. All words serve as clear pronunciation models for Dutch sounds that differ from English.</p><h3 id="vocabulary-by-phonetic-category" tabindex="-1">Vocabulary by Phonetic Category <a class="header-anchor" href="#vocabulary-by-phonetic-category" aria-label="Permalink to &quot;Vocabulary by Phonetic Category&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Category</th><th>Count</th><th>Examples</th></tr></thead><tbody><tr><td>Alphabet Letters</td><td>5</td><td>a, bee, ee, ie, uu</td></tr><tr><td>Short Vowels</td><td>5</td><td>man, bed, vis, pot, bus</td></tr><tr><td>Long Vowels</td><td>5</td><td>maan, been, fiets, boom, muur</td></tr><tr><td>Diphthongs</td><td>5</td><td>huis, oud, auto, ei, ijs</td></tr><tr><td>Consonants</td><td>4</td><td>goed, hallo, rood, water</td></tr><tr><td>Stress Patterns</td><td>1</td><td>tafel</td></tr></tbody></table><h3 id="full-vocabulary-table" tabindex="-1">Full Vocabulary Table <a class="header-anchor" href="#full-vocabulary-table" aria-label="Permalink to &quot;Full Vocabulary Table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dutch</th><th>English</th><th>Article</th><th>Plural</th><th>Pronunciation</th><th>POS</th><th>Freq</th><th>Topic</th><th>Example (Dutch)</th><th>Example (English)</th><th>Notes</th></tr></thead><tbody><tr><td>a</td><td>the letter a</td><td>--</td><td>--</td><td>AH</td><td>noun</td><td>1</td><td>alphabet</td><td>Dit is de letter a.</td><td>This is the letter a.</td><td>Alphabet name; introduces an open AH sound.</td></tr><tr><td>bee</td><td>the letter b</td><td>--</td><td>--</td><td>BAY</td><td>noun</td><td>2</td><td>alphabet</td><td>Dit is de letter bee.</td><td>This is the letter b.</td><td>Alphabet name; Dutch long ee letter-name pattern.</td></tr><tr><td>ee</td><td>the letter e</td><td>--</td><td>--</td><td>AY</td><td>noun</td><td>3</td><td>alphabet</td><td>De letter ee klinkt als AY.</td><td>The letter e sounds like AY.</td><td>Alphabet name; Dutch letter e differs from English.</td></tr><tr><td>ie</td><td>the letter i</td><td>--</td><td>--</td><td>EE</td><td>noun</td><td>4</td><td>alphabet</td><td>Dit is de letter ie.</td><td>This is the letter i.</td><td>Alphabet name; Dutch i is named with EE sound.</td></tr><tr><td>uu</td><td>the letter u</td><td>--</td><td>--</td><td>UU</td><td>noun</td><td>5</td><td>alphabet</td><td>De letter uu is moeilijk.</td><td>The letter u is difficult.</td><td>Alphabet name; rounded Dutch UU sound.</td></tr><tr><td>man</td><td>man</td><td>de</td><td>mannen</td><td>MAHN</td><td>noun</td><td>6</td><td>short_vowels</td><td>Dit is een man.</td><td>This is a man.</td><td>Clear short a in closed syllable; contrast with maan.</td></tr><tr><td>bed</td><td>bed</td><td>het</td><td>bedden</td><td>BED</td><td>noun</td><td>7</td><td>short_vowels</td><td>Dit is een bed.</td><td>This is a bed.</td><td>Clear short e; similar to English bed.</td></tr><tr><td>vis</td><td>fish</td><td>de</td><td>vissen</td><td>VISS</td><td>noun</td><td>8</td><td>short_vowels</td><td>Dit is een vis.</td><td>This is a fish.</td><td>Clear short i like English sit.</td></tr><tr><td>pot</td><td>pot</td><td>de</td><td>potten</td><td>POT</td><td>noun</td><td>9</td><td>short_vowels</td><td>Dit is een pot.</td><td>This is a pot.</td><td>Clear short o in closed syllable.</td></tr><tr><td>bus</td><td>bus</td><td>de</td><td>bussen</td><td>BUUS</td><td>noun</td><td>10</td><td>short_vowels</td><td>Dit is een bus.</td><td>This is a bus.</td><td>Short Dutch u; rounded sound.</td></tr><tr><td>maan</td><td>moon</td><td>de</td><td>manen</td><td>MAHN</td><td>noun</td><td>11</td><td>long_vowels</td><td>Dit is de maan.</td><td>This is the moon.</td><td>Long aa; pairs with man to show vowel length contrast.</td></tr><tr><td>been</td><td>leg</td><td>het</td><td>benen</td><td>BAYN</td><td>noun</td><td>12</td><td>long_vowels</td><td>Dit is een been.</td><td>This is a leg.</td><td>Long ee approximated as AY without English glide.</td></tr><tr><td>fiets</td><td>bicycle</td><td>de</td><td>fietsen</td><td>FEETS</td><td>noun</td><td>13</td><td>long_vowels</td><td>Dit is een fiets.</td><td>This is a bicycle.</td><td>Long ie with clear EE sound in common word.</td></tr><tr><td>boom</td><td>tree</td><td>de</td><td>bomen</td><td>BOHM</td><td>noun</td><td>14</td><td>long_vowels</td><td>Dit is een boom.</td><td>This is a tree.</td><td>Long oo; useful for showing double-vowel spelling.</td></tr><tr><td>muur</td><td>wall</td><td>de</td><td>muren</td><td>MUUR</td><td>noun</td><td>15</td><td>long_vowels</td><td>Dit is een muur.</td><td>This is a wall.</td><td>Long uu; reinforces rounded lips and sustained vowel.</td></tr><tr><td>huis</td><td>house</td><td>het</td><td>huizen</td><td>HOWS</td><td>noun</td><td>16</td><td>diphthongs</td><td>Dit is een huis.</td><td>This is a house.</td><td>Key ui diphthong; no exact English equivalent.</td></tr><tr><td>oud</td><td>old</td><td>--</td><td>--</td><td>OWT</td><td>adjective</td><td>17</td><td>diphthongs</td><td>Dit is oud.</td><td>This is old.</td><td>Clear ou diphthong, similar to OW in English now.</td></tr><tr><td>auto</td><td>car</td><td>de</td><td>auto&#39;s</td><td>OW-toh</td><td>noun</td><td>18</td><td>diphthongs</td><td>Dit is een auto.</td><td>This is a car.</td><td>Clear au spelling; useful contrast with ou.</td></tr><tr><td>ei</td><td>egg</td><td>het</td><td>eieren</td><td>EYE</td><td>noun</td><td>19</td><td>diphthongs</td><td>Dit is een ei.</td><td>This is an egg.</td><td>Short word isolating ei diphthong.</td></tr><tr><td>ijs</td><td>ice</td><td>het</td><td>--</td><td>EYES</td><td>noun</td><td>20</td><td>diphthongs</td><td>Dit is ijs.</td><td>This is ice.</td><td>Clear ij example; teaches ij and ei share same sound.</td></tr><tr><td>goed</td><td>good</td><td>--</td><td>--</td><td>KHOOT</td><td>adjective</td><td>21</td><td>consonants</td><td>Dit is goed.</td><td>This is good.</td><td>Dutch g is back-of-throat sound.</td></tr><tr><td>hallo</td><td>hello</td><td>--</td><td>--</td><td>HAH-loh</td><td>interjection</td><td>22</td><td>consonants</td><td>Hallo, dit is Nederlands.</td><td>Hello, this is Dutch.</td><td>Simple h example; distinguishes from guttural g.</td></tr><tr><td>rood</td><td>red</td><td>--</td><td>--</td><td>ROHT</td><td>adjective</td><td>23</td><td>consonants</td><td>Dit is rood.</td><td>This is red.</td><td>Dutch r may be rolled or throaty.</td></tr><tr><td>water</td><td>water</td><td>het</td><td>--</td><td>VAH-ter</td><td>noun</td><td>24</td><td>consonants</td><td>Dit is water.</td><td>This is water.</td><td>Dutch w between English v and w.</td></tr><tr><td>tafel</td><td>table</td><td>de</td><td>tafels</td><td>TAH-fuhl</td><td>noun</td><td>25</td><td>stress_patterns</td><td>Dit is een tafel.</td><td>This is a table.</td><td>Shows common Dutch first-syllable stress.</td></tr></tbody></table><h3 id="quality-verification" tabindex="-1">Quality Verification <a class="header-anchor" href="#quality-verification" aria-label="Permalink to &quot;Quality Verification&quot;">​</a></h3><p>✅ All 25 words present and ranked<br> ✅ All articles correct (de/het/--)<br> ✅ All pronunciations provided (English approximations, no IPA)<br> ✅ All example sentences use only A0 grammar<br> ✅ No grammar structures beyond present tense &quot;is/are&quot;<br> ✅ All topics within phonetic focus area<br> ✅ Frequency ranking reflects teaching usefulness</p><hr><h2 id="a1-vocabulary-topics" tabindex="-1">A1 Vocabulary Topics <a class="header-anchor" href="#a1-vocabulary-topics" aria-label="Permalink to &quot;A1 Vocabulary Topics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Level</th><th>Target</th><th>Lessons</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td>Food</td><td>A1</td><td>30</td><td>A1-02, A1-03</td><td>Pending</td><td>Common foods and drinks</td></tr><tr><td>Transportation</td><td>A1</td><td>15</td><td>A1-04</td><td>Pending</td><td>Bus, train, car, bike</td></tr><tr><td>Clothing</td><td>A1</td><td>20</td><td>A1-05, A1-06</td><td>Pending</td><td>Common clothing items</td></tr><tr><td>Work</td><td>A1</td><td>15</td><td>A1-07</td><td>Pending</td><td>Common professions</td></tr></tbody></table><hr><h2 id="a2-vocabulary-topics" tabindex="-1">A2 Vocabulary Topics <a class="header-anchor" href="#a2-vocabulary-topics" aria-label="Permalink to &quot;A2 Vocabulary Topics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Level</th><th>Target</th><th>Lessons</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td>Housing</td><td>A2</td><td>25</td><td>A2-02, A2-03</td><td>Pending</td><td>Apartment, rent, furniture</td></tr><tr><td>Healthcare</td><td>A2</td><td>20</td><td>A2-04</td><td>Pending</td><td>Doctor, pharmacy, illnesses</td></tr><tr><td>Government</td><td>A2</td><td>15</td><td>A2-05</td><td>Pending</td><td>Official forms, processes</td></tr><tr><td>Money</td><td>A2</td><td>12</td><td>A2-06</td><td>Pending</td><td>Prices, payment, currency</td></tr></tbody></table><hr><h2 id="b1-vocabulary-topics" tabindex="-1">B1 Vocabulary Topics <a class="header-anchor" href="#b1-vocabulary-topics" aria-label="Permalink to &quot;B1 Vocabulary Topics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Level</th><th>Target</th><th>Lessons</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td>Opinions</td><td>B1</td><td>20</td><td>B1-01, B1-02</td><td>Pending</td><td>Like, dislike, agree, disagree</td></tr><tr><td>News</td><td>B1</td><td>30</td><td>B1-03, B1-04</td><td>Pending</td><td>Politics, current events</td></tr><tr><td>Culture</td><td>B1</td><td>25</td><td>B1-05, B1-06</td><td>Pending</td><td>Art, music, traditions</td></tr><tr><td>Business</td><td>B1</td><td>25</td><td>B1-07</td><td>Pending</td><td>Meetings, emails, reports</td></tr></tbody></table><hr><h2 id="cumulative-vocabulary-targets" tabindex="-1">Cumulative Vocabulary Targets <a class="header-anchor" href="#cumulative-vocabulary-targets" aria-label="Permalink to &quot;Cumulative Vocabulary Targets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Level</th><th>Total Words</th><th>Frequency Rank</th><th>Status</th></tr></thead><tbody><tr><td>A0</td><td>350-500</td><td>1-500</td><td>Pending</td></tr><tr><td>A1</td><td>1,000-1,500</td><td>1-1500</td><td>Pending</td></tr><tr><td>A2</td><td>1,800-2,200</td><td>1-2200</td><td>Pending</td></tr><tr><td>B1</td><td>2,500-3,500</td><td>1-3500</td><td>Pending</td></tr></tbody></table><hr><h2 id="master-vocabulary-database" tabindex="-1">Master Vocabulary Database <a class="header-anchor" href="#master-vocabulary-database" aria-label="Permalink to &quot;Master Vocabulary Database&quot;">​</a></h2><p>All vocabulary is stored in <code>shared/vocabulary/</code>, split into four files by part of speech:</p><p><strong>Location:</strong> <code>shared/vocabulary/nouns.csv</code>, <code>verbs.csv</code>, <code>adjectives.csv</code>, <code>other.csv</code></p><p><strong>Shared fields (all files):</strong></p><ul><li>Dutch</li><li>English</li><li>Pronunciation</li><li>CEFR Level</li><li>Lesson Introduced</li><li>Frequency Rank</li><li>Topic</li><li>Example Sentence</li><li>Example Translation</li><li>Notes</li></ul><p><strong>Nouns.csv adds:</strong> Article (de/het), Plural, Diminutive <strong>Verbs.csv adds:</strong> Verb Type, Present tense (ik / jij-u-hij-zij-het / wij-jullie-zij), Simple Past (singular/plural), Auxiliary, Past Participle <strong>Adjectives.csv adds:</strong> Comparative, Superlative, Inflected Form <strong>Other.csv adds:</strong> Part of Speech (adverb, preposition, conjunction, pronoun, article, determiner, interjection, numeral, phrase)</p><p>See <code>docs/VOCABULARY_STANDARD.md</code> for the full field-by-field rules.</p><p><strong>Current Status:</strong> Only A0-01 populated (~25 words); the rest is to be populated in Phase 2.</p><hr><h2 id="generated-exports" tabindex="-1">Generated Exports <a class="header-anchor" href="#generated-exports" aria-label="Permalink to &quot;Generated Exports&quot;">​</a></h2><p>From the four vocabulary files, we generate:</p><h3 id="by-level" tabindex="-1">By Level <a class="header-anchor" href="#by-level" aria-label="Permalink to &quot;By Level&quot;">​</a></h3><ul><li><code>shared/csv/A0.csv</code> -- All A0 vocabulary</li><li><code>shared/csv/A1.csv</code> -- All A1 vocabulary</li><li><code>shared/csv/A2.csv</code> -- All A2 vocabulary</li><li><code>shared/csv/B1.csv</code> -- All B1 vocabulary</li></ul><h3 id="by-lesson" tabindex="-1">By Lesson <a class="header-anchor" href="#by-lesson" aria-label="Permalink to &quot;By Lesson&quot;">​</a></h3><ul><li><code>shared/csv/lessons/A0-01.csv</code> -- Vocabulary for A0-01</li><li><code>shared/csv/lessons/A0-02.csv</code> -- Vocabulary for A0-02</li><li>(One for each lesson)</li></ul><h3 id="by-topic" tabindex="-1">By Topic <a class="header-anchor" href="#by-topic" aria-label="Permalink to &quot;By Topic&quot;">​</a></h3><ul><li><code>shared/csv/topics/Family.csv</code> -- All family vocabulary</li><li><code>shared/csv/topics/Food.csv</code> -- All food vocabulary</li><li>(One for each topic)</li></ul><h3 id="anki-decks" tabindex="-1">Anki Decks <a class="header-anchor" href="#anki-decks" aria-label="Permalink to &quot;Anki Decks&quot;">​</a></h3><ul><li><code>shared/anki/A0.apkg</code> -- Anki deck for A0</li><li><code>shared/anki/Family.apkg</code> -- Anki deck for family vocabulary</li><li>(Additional decks as needed)</li></ul><hr><h2 id="high-frequency-words-strategy" tabindex="-1">High-Frequency Words Strategy <a class="header-anchor" href="#high-frequency-words-strategy" aria-label="Permalink to &quot;High-Frequency Words Strategy&quot;">​</a></h2><p>Vocabulary is selected based on:</p><ol><li><strong>Frequency</strong> -- Most common words first</li><li><strong>Usefulness</strong> -- Essential for communication</li><li><strong>Context</strong> -- Grouped by topic/situation</li><li><strong>Difficulty</strong> -- Easier pronunciation/spelling first</li></ol><p>The &quot;Frequency Rank&quot; in the master database reflects this, with lower numbers being more frequent.</p><hr><h2 id="quality-rules" tabindex="-1">Quality Rules <a class="header-anchor" href="#quality-rules" aria-label="Permalink to &quot;Quality Rules&quot;">​</a></h2><p>Every vocabulary entry must:</p><ul><li>[ ] Exist in the correct <code>shared/vocabulary/*.csv</code> file (nouns/verbs/adjectives/other)</li><li>[ ] Have pronunciation guidance</li><li>[ ] Have an example sentence</li><li>[ ] Be appropriate for its CEFR level</li><li>[ ] Not be a duplicate</li><li>[ ] Have all required fields</li><li>[ ] Use only known grammar in the example</li></ul><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ol><li>Complete <code>nouns.csv</code>, <code>verbs.csv</code>, <code>adjectives.csv</code>, <code>other.csv</code> with all A0-B1 vocabulary</li><li>Generate CSV exports for each level</li><li>Generate CSV exports for each lesson</li><li>Generate CSV exports for each topic</li><li>Generate Anki decks</li><li>Verify no duplicates</li><li>Verify all examples use only known grammar</li></ol>`,72)])])}const b=d(r,[["render",s]]);export{p as __pageData,b as default};
